// Staff review of generated questions (design §4.3), shared by the job bank
// and by an interview's gap probes. The rules are the same for both:
// - the model's original is never modified; an edit is stored beside it;
// - an edit keeps the original's kind and passes the same filters as a
//   generated question (no protected category, nothing generic);
// - a replacement is generated by one model call within the owner's budget,
//   and the replaced question is kept, marked removed, and linked.
import type { Sql, Tx } from "../db/client.ts";
import { jsonb } from "../db/client.ts";
import type { BankEdit, QuestionContent } from "../contract/index.ts";
import {
  effectiveContent,
  findQuestion,
  insertQuestions,
  listQuestions,
  type QuestionParent,
  type QuestionRow,
} from "../db/banks.ts";
import { LlmCallError } from "../llm/run.ts";
import {
  BudgetExceededError,
  claimRegeneration,
  refundRegeneration,
  type BudgetOwner,
  type Ceilings,
} from "../orchestrator/budget.ts";
import { contentProblem } from "../planner/validate.ts";
import { errorReply, type Reply } from "./http.ts";

export type SimpleEdit = Exclude<BankEdit, { op: "regenerate" }>;

// approve / remove / restore / edit on a question already locked FOR UPDATE.
// Returns an error reply, or null when the change was applied.
export async function applySimpleEdit(
  tx: Tx,
  question: QuestionRow,
  edit: SimpleEdit
): Promise<Reply | null> {
  switch (edit.op) {
    case "approve":
      if (question.status === "removed") return errorReply(409, "question_not_editable");
      await tx`
        update bank_questions set status = 'approved', updated_at = now()
        where id = ${question.id}`;
      return null;
    case "remove":
      await tx`
        update bank_questions set status = 'removed', updated_at = now()
        where id = ${question.id}`;
      return null;
    case "restore":
      if (question.status !== "removed") return null;
      await tx`
        update bank_questions set status = 'pending', updated_at = now()
        where id = ${question.id}`;
      return null;
    case "edit": {
      if (question.status === "removed") return errorReply(409, "question_not_editable");
      if (edit.content.kind !== question.kind) return errorReply(422, "kind_mismatch");
      const problem = contentProblem(edit.content);
      if (problem) return errorReply(422, problem);
      // Staff's version goes to `edited`; `original` stays the model's
      // (the database refuses a change to it as well).
      await tx`
        update bank_questions
        set edited = ${tx.json(jsonb(edit.content))}, status = 'approved', updated_at = now()
        where id = ${question.id}`;
      return null;
    }
  }
}

export type RegenerateSpec = {
  owner: BudgetOwner;
  parent: QuestionParent;
  // Re-reads and locks the parent once the model has answered, and returns
  // an error reply when it can no longer be edited (locked meanwhile, …).
  lockParent: (tx: Tx) => Promise<Reply | null>;
  // One model call. null = the candidate did not survive the filters.
  generate: (question: QuestionRow, existingTexts: string[]) => Promise<QuestionContent | null>;
};

// "Generate a replacement". The model call runs outside any transaction (a
// call can take many seconds), so the parent and the question are checked
// again before the result is written.
export async function regenerateQuestion(
  deps: { sql: Sql; ceilings: Ceilings },
  spec: RegenerateSpec,
  questionId: string
): Promise<Reply | null> {
  const all = await listQuestions(deps.sql, spec.parent);
  const question = all.find((q) => q.id === questionId);
  if (!question) return errorReply(404, "not_found");
  if (question.status === "removed") return errorReply(409, "question_not_editable");

  if (!(await claimRegeneration(deps.sql, spec.owner, deps.ceilings))) {
    return errorReply(429, "regeneration_limit");
  }

  // The replacement must differ from everything already proposed, staff's
  // wording and removed questions included.
  const existingTexts = all.map((q) => effectiveContent(q).text_ar);
  let replacement: QuestionContent | null;
  try {
    replacement = await spec.generate(question, existingTexts);
  } catch (err) {
    if (err instanceof BudgetExceededError) {
      // Refused before any call was made: the regeneration is given back.
      await refundRegeneration(deps.sql, spec.owner);
      return errorReply(429, "regeneration_limit");
    }
    if (err instanceof LlmCallError) return errorReply(502, "generation_failed");
    throw err;
  }
  // The original question stays exactly as it was.
  if (!replacement) return errorReply(502, "generation_failed");

  return deps.sql.begin(async (tx) => {
    const blocked = await spec.lockParent(tx);
    if (blocked) return blocked;
    const current = await findQuestion(tx, spec.parent, questionId);
    if (!current) return errorReply(404, "not_found");
    if (current.status === "removed") return errorReply(409, "question_not_editable");
    await tx`
      update bank_questions set status = 'removed', updated_at = now()
      where id = ${current.id}`;
    await insertQuestions(tx, spec.parent, [replacement], {
      startPosition: current.position,
      replaces: current.id,
    });
    return null;
  });
}
